task.code-example:

function generateWidgetCode(settings: WidgetSettings): string {
  return `<script src="https://veriply.io/widget.js"
        data-bot-id="${settings.botId}"
        data-position="${settings.position}"
        data-primary-color="${settings.primaryColor}"
        data-welcome-message="${escapeHtml(settings.welcomeMessage)}"
        ${settings.autoOpen ? 'data-auto-open="true"' : ''}>
</script>`;
}


// Widget initialization logic
(function() {
  const script = document.currentScript as HTMLScriptElement;
  const botId = script.dataset.botId;
  const position = script.dataset.position || 'bottom-right';
  const primaryColor = script.dataset.primaryColor || '#3B82F6';
  const welcomeMessage = script.dataset.welcomeMessage || 'Hi! How can I help?';
  const autoOpen = script.dataset.autoOpen === 'true';

  // Create widget container
  const container = document.createElement('div');
  container.id = 'veriply-widget';
  container.className = `veriply-widget veriply-widget-${position}`;

  // Create iframe
  const iframe = document.createElement('iframe');
  iframe.src = `https://veriply.io/chat/${botId}?embedded=true`;
  iframe.sandbox = 'allow-same-origin allow-forms allow-popups allow-scripts';
  iframe.style.border = 'none';
  iframe.style.width = '100%';
  iframe.style.height = '100%';

  container.appendChild(iframe);
  document.body.appendChild(container);

  // Apply custom styling
  container.style.setProperty('--primary-color', primaryColor);

  if (autoOpen) {
    container.classList.add('veriply-widget-open');
  }
})();

typescript-interfaces.interface:

interface WidgetSettings {
  botId: string;
  position: 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left';
  primaryColor: string; // hex color
  welcomeMessage: string; // max 200 chars
  autoOpen: boolean;
}


interface WidgetConfig {
  id: string;
  botId: string;
  position: string;
  primaryColor: string;
  welcomeMessage: string;
  autoOpen: boolean;
  createdAt: Date;
  updatedAt: Date;
}
